using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
public static class SetupWheelDrive {
 public static string Main(){var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(EditorApplication.isPlaying||scene.path!="Assets/Scenes/TestTrackScene.unity")throw new System.Exception("Expected test track in Edit mode.");var movement=Object.FindAnyObjectByType<TestDriveMovement>();var car=movement.transform;var body=car.GetComponent<Rigidbody>();Undo.RecordObject(body,"Set wheel-driven body");body.constraints=RigidbodyConstraints.None;body.mass=1200;body.centerOfMass=new Vector3(0,.45f,0);body.angularDamping=.5f;body.linearDamping=.02f;body.interpolation=RigidbodyInterpolation.Interpolate;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;
 var box=car.GetComponent<BoxCollider>();Undo.RecordObject(box,"Fit collider to body without tires");var mesh=car.GetComponent<MeshFilter>().sharedMesh;box.center=mesh.bounds.center;box.size=mesh.bounds.size;
 const string materialPath="Assets/Environments/TestTrack/WheelDriveBody.physicMaterial";var material=AssetDatabase.LoadAssetAtPath<PhysicsMaterial>(materialPath);if(!material){material=new PhysicsMaterial("WheelDriveBody"){dynamicFriction=.3f,staticFriction=.4f,bounciness=0,frictionCombine=PhysicsMaterialCombine.Average,bounceCombine=PhysicsMaterialCombine.Minimum};AssetDatabase.CreateAsset(material,materialPath);}box.sharedMaterial=material;
 var old=car.Find("Wheel Colliders");if(old)throw new System.Exception("Wheel rig already exists; refusing duplicate.");var parent=new GameObject("Wheel Colliders");Undo.RegisterCreatedObjectUndo(parent,"Create wheel rig");parent.transform.SetParent(car,false);
 var so=new SerializedObject(movement);var wheels=so.FindProperty("wheels");wheels.arraySize=4;var labels=new[]{"FL","FR","BL","BR"};var report="";
 for(int i=0;i<4;i++){var visual=car.Find("Sport Car_39 "+labels[i]+" Tire");if(!visual)throw new System.Exception("Missing wheel "+labels[i]);var go=new GameObject(labels[i]+" WheelCollider");Undo.RegisterCreatedObjectUndo(go,"Create wheel collider");go.transform.SetParent(parent.transform,false);go.transform.localPosition=visual.localPosition+Vector3.up*.125f;var wheel=go.AddComponent<WheelCollider>();wheel.radius=visual.GetComponent<MeshFilter>().sharedMesh.bounds.extents.y;wheel.suspensionDistance=.25f;wheel.mass=25;wheel.wheelDampingRate=.4f;wheel.forceAppPointDistance=.15f;var spring=wheel.suspensionSpring;spring.spring=35000;spring.damper=4500;spring.targetPosition=.5f;wheel.suspensionSpring=spring;var entry=wheels.GetArrayElementAtIndex(i);entry.FindPropertyRelative("collider").objectReferenceValue=wheel;entry.FindPropertyRelative("visual").objectReferenceValue=visual;entry.FindPropertyRelative("steering").boolValue=i<2;entry.FindPropertyRelative("driven").boolValue=i>=2;report+=labels[i]+" radius="+wheel.radius.ToString("F3")+"; ";}
 so.ApplyModifiedProperties();PrefabUtility.RecordPrefabInstancePropertyModifications(body);PrefabUtility.RecordPrefabInstancePropertyModifications(box);EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Selection.activeGameObject=parent;return report+"Body box center="+box.center+", size="+box.size+". Saved wheel drive scene.";}
}
